import React, { useState, useEffect, useRef } from 'react';
import { 
  DollarSign, 
  Users, 
  ShoppingBag, 
  TrendingUp, 
  ArrowUp, 
  ArrowDown,
  Zap,
  Sparkles,
  Target,
  BarChart3
} from 'lucide-react';

const StatsCards = () => {
  const [isVisible, setIsVisible] = useState(false);
  const [hoveredIndex, setHoveredIndex] = useState(null);
  const cardRefs = useRef([]);

  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            setIsVisible(true);
            observer.unobserve(entry.target);
          }
        });
      },
      { threshold: 0.1, rootMargin: '50px' }
    );

    cardRefs.current.forEach((ref) => ref && observer.observe(ref));

    return () => observer.disconnect();
  }, []);

  const stats = [
    { 
      id: 1,
      title: 'Revenu total', 
      value: '$54,231', 
      change: '+12.5%', 
      icon: DollarSign, 
      color: 'primary', 
      trend: 'up',
      description: 'Ce mois',
      progress: 78,
      sparkleCount: 3
    },
    { 
      id: 2,
      title: 'Nouveaux utilisateurs', 
      value: '3,254', 
      change: '+8.2%', 
      icon: Users, 
      color: 'accent', 
      trend: 'up',
      description: '30 derniers jours',
      progress: 65,
      sparkleCount: 2
    },
    { 
      id: 3,
      title: 'Commandes', 
      value: '1,243', 
      change: '+5.7%', 
      icon: ShoppingBag, 
      color: 'secondary', 
      trend: 'up',
      description: 'Cette semaine',
      progress: 85,
      sparkleCount: 4
    },
    { 
      id: 4,
      title: 'Taux de conversion', 
      value: '3.42%', 
      change: '-1.2%', 
      icon: TrendingUp, 
      color: 'warning', 
      trend: 'down',
      description: 'Comparaison mensuelle',
      progress: 42,
      sparkleCount: 1
    },
  ];

  const getColorConfig = (color) => {
    const configs = {
      primary: {
        gradient: 'from-primary-500/10 via-primary-500/5 to-transparent',
        hoverGradient: 'from-primary-500/20 via-primary-500/10 to-transparent',
        iconBg: 'bg-primary-500/10 dark:bg-primary-500/20',
        iconColor: 'text-primary-600 dark:text-primary-400',
        glow: 'shadow-primary-500/20',
        progress: 'bg-gradient-to-r from-primary-500 to-primary-400'
      },
      accent: {
        gradient: 'from-accent-500/10 via-accent-500/5 to-transparent',
        hoverGradient: 'from-accent-500/20 via-accent-500/10 to-transparent',
        iconBg: 'bg-accent-500/10 dark:bg-accent-500/20',
        iconColor: 'text-accent-600 dark:text-accent-400',
        glow: 'shadow-accent-500/20',
        progress: 'bg-gradient-to-r from-accent-500 to-accent-400'
      },
      secondary: {
        gradient: 'from-secondary-500/10 via-secondary-500/5 to-transparent',
        hoverGradient: 'from-secondary-500/20 via-secondary-500/10 to-transparent',
        iconBg: 'bg-secondary-500/10 dark:bg-secondary-500/20',
        iconColor: 'text-secondary-600 dark:text-secondary-400',
        glow: 'shadow-secondary-500/20',
        progress: 'bg-gradient-to-r from-secondary-500 to-secondary-400'
      },
      warning: {
        gradient: 'from-warning-500/10 via-warning-500/5 to-transparent',
        hoverGradient: 'from-warning-500/20 via-warning-500/10 to-transparent',
        iconBg: 'bg-warning-500/10 dark:bg-warning-500/20',
        iconColor: 'text-warning-600 dark:text-warning-400',
        glow: 'shadow-warning-500/20',
        progress: 'bg-gradient-to-r from-warning-500 to-warning-400'
      },
    };
    return configs[color] || configs.primary;
  };

  const SparkleEffect = ({ count, color }) => (
    <div className="absolute inset-0 overflow-hidden pointer-events-none">
      {Array.from({ length: count }).map((_, i) => (
        <div
          key={i}
          className={`absolute w-1 h-1 ${color} rounded-full animate-float-sparkle`}
          style={{
            left: `${10 + Math.random() * 80}%`,
            top: `${10 + Math.random() * 80}%`,
            animationDelay: `${i * 0.3}s`,
            animationDuration: `${2 + Math.random() * 3}s`
          }}
        />
      ))}
    </div>
  );

  return (
    <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4 sm:gap-6 mb-8 lg:mb-10">
      {stats.map((stat, index) => {
        const Icon = stat.icon;
        const colors = getColorConfig(stat.color);
        const animationDelay = index * 100;

        return (
          <div
            key={stat.id}
            ref={(el) => {
              cardRefs.current[index] = el;
            }}
            className={`relative bg-white/80 dark:bg-neutral-900/80 backdrop-blur-xl 
              rounded-2xl p-6 sm:p-7 transition-all duration-500 ease-out
              border border-white/40 dark:border-neutral-800/50
              hover:border-white/60 dark:hover:border-neutral-700/50
              overflow-hidden group cursor-pointer
              ${isVisible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-8'}
              hover:scale-[1.02] hover:shadow-2xl hover:shadow-neutral-500/10 dark:hover:shadow-black/30
              ${hoveredIndex === index ? colors.glow : 'shadow-lg shadow-neutral-200/50 dark:shadow-black/20'}`}
            style={{
              transitionDelay: `${animationDelay}ms`,
              animationDelay: `${animationDelay}ms`,
            }}
            onMouseEnter={() => setHoveredIndex(index)}
            onMouseLeave={() => setHoveredIndex(null)}
            role="region"
            aria-label={`Statistique: ${stat.title}`}
          >
            {/* Effets de fond animés */}
            <div 
              className={`absolute inset-0 bg-gradient-to-br ${colors.gradient} 
                group-hover:${colors.hoverGradient} transition-all duration-700`}
            />

            {/* Effet de brillance sur hover */}
            <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/5 to-transparent 
              -translate-x-full group-hover:translate-x-full transition-transform duration-1000" />

            {/* Effets de particules */}
            <SparkleEffect 
              count={stat.sparkleCount} 
              color={stat.trend === 'up' ? 'bg-accent-400/60' : 'bg-warning-400/60'} 
            />

            {/* Badge de tendance flottant */}
            <div className={`absolute -top-2 -right-2 w-12 h-12 rounded-full 
              ${stat.trend === 'up' ? 'bg-accent-500/10' : 'bg-red-500/10'} 
              backdrop-blur-sm border ${stat.trend === 'up' ? 'border-accent-500/20' : 'border-red-500/20'}
              flex items-center justify-center
              ${isVisible ? 'scale-100 rotate-0' : 'scale-0 rotate-45'}
              transition-all duration-700 ease-out`}
              style={{ transitionDelay: `${animationDelay + 200}ms` }}
            >
              {stat.trend === 'up' ? (
                <ArrowUp className="h-5 w-5 text-accent-600 dark:text-accent-400" />
              ) : (
                <ArrowDown className="h-5 w-5 text-red-600 dark:text-red-400" />
              )}
            </div>

            <div className="relative z-10">
              {/* En-tête avec icône et badge */}
              <div className="flex items-start justify-between mb-6">
                <div className={`p-3 rounded-xl ${colors.iconBg} ${colors.iconColor} 
                  transition-all duration-500 group-hover:scale-110 group-hover:rotate-12
                  ${isVisible ? 'opacity-100 scale-100' : 'opacity-0 scale-90'}`}
                  style={{ transitionDelay: `${animationDelay + 100}ms` }}
                >
                  <Icon className="h-6 w-6 sm:h-7 sm:w-7" />
                </div>

                <div className={`flex items-center gap-1.5 px-3 py-1.5 rounded-full text-sm font-semibold 
                  backdrop-blur-sm transition-all duration-500
                  ${stat.trend === 'up' 
                    ? 'bg-accent-500/15 text-accent-700 dark:text-accent-300 border border-accent-500/30' 
                    : 'bg-red-500/15 text-red-700 dark:text-red-300 border border-red-500/30'
                  }
                  ${isVisible ? 'translate-x-0 opacity-100' : 'translate-x-4 opacity-0'}`}
                  style={{ transitionDelay: `${animationDelay + 150}ms` }}
                >
                  {stat.trend === 'up' ? (
                    <ArrowUp className="h-4 w-4" />
                  ) : (
                    <ArrowDown className="h-4 w-4" />
                  )}
                  <span>{stat.change}</span>
                </div>
              </div>

              {/* Valeur principale */}
              <div className="mb-2 overflow-hidden">
                <h3 
                  className={`text-2xl sm:text-3xl font-bold text-neutral-900 dark:text-white 
                    transition-all duration-500
                    ${isVisible ? 'translate-y-0 opacity-100' : 'translate-y-4 opacity-0'}
                    group-hover:text-primary-600 dark:group-hover:text-primary-400`}
                  style={{ transitionDelay: `${animationDelay + 200}ms` }}
                >
                  {stat.value}
                </h3>
              </div>

              {/* Titre et description */}
              <p className="text-base font-semibold text-neutral-700 dark:text-neutral-300 mb-1">
                {stat.title}
              </p>

              <p className="text-sm text-neutral-500 dark:text-neutral-500 mb-6">
                {stat.description}
              </p>

              {/* Barre de progression avec animation */}
              <div className="space-y-2">
                <div className="flex justify-between items-center text-sm">
                  <span className="text-neutral-600 dark:text-neutral-400 font-medium">
                    Progression
                  </span>
                  <span className={`font-bold ${stat.trend === 'up' ? 'text-accent-600' : 'text-red-600'}`}>
                    {stat.progress}%
                  </span>
                </div>

                <div className="relative h-2 w-full bg-neutral-200/50 dark:bg-neutral-800/50 
                  rounded-full overflow-hidden backdrop-blur-sm">
                  {/* Fond animé */}
                  <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/10 to-transparent 
                    -translate-x-full group-hover:translate-x-full transition-transform duration-1000" />

                  {/* Barre de progression animée */}
                  <div 
                    className={`h-full rounded-full ${colors.progress} relative overflow-hidden
                      transition-all duration-1000 ease-out
                      ${isVisible ? 'w-full' : 'w-0'}`}
                    style={{ 
                      width: isVisible ? `${stat.progress}%` : '0%',
                      transitionDelay: `${animationDelay + 300}ms`
                    }}
                  >
                    {/* Effet de scintillement sur la barre */}
                    <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/30 to-transparent 
                      -translate-x-full animate-shine" />
                  </div>
                </div>

                {/* Indicateurs de progression */}
                <div className="flex justify-between text-xs text-neutral-500 dark:text-neutral-500">
                  <span>0%</span>
                  <span className={`flex items-center gap-1 ${stat.trend === 'up' ? 'text-accent-600' : 'text-red-600'}`}>
                    {stat.trend === 'up' ? (
                      <>
                        <TrendingUp className="h-3 w-3" />
                        Objectif atteint à {stat.progress}%
                      </>
                    ) : (
                      <>
                        <Target className="h-3 w-3" />
                        Objectif à {stat.progress}%
                      </>
                    )}
                  </span>
                  <span>100%</span>
                </div>
              </div>

              {/* Badge d'indicateur de performance */}
              <div className={`mt-4 inline-flex items-center gap-2 px-3 py-1.5 rounded-full text-xs font-medium
                ${stat.trend === 'up' 
                  ? 'bg-accent-500/10 text-accent-700 dark:text-accent-300' 
                  : 'bg-warning-500/10 text-warning-700 dark:text-warning-300'
                }
                transition-all duration-500
                ${isVisible ? 'translate-y-0 opacity-100' : 'translate-y-2 opacity-0'}`}
                style={{ transitionDelay: `${animationDelay + 400}ms` }}
              >
                <Zap className="h-3 w-3" />
                {stat.trend === 'up' ? 'Performance élevée' : 'Amélioration nécessaire'}
              </div>
            </div>
          </div>
        );
      })}
    </div>
  );
};

export default StatsCards;
